import{_ as e,c as t,o as n,a3 as r}from"./chunks/framework.CoV49S2T.js";const p=JSON.parse('{"title":"Guía de uso","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/usage.md","filePath":"es/guide/usage.md","lastUpdated":1786595765000}'),o={name:"es/guide/usage.md"};function i(l,a,s,c,d,u){return n(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="guia-de-uso" tabindex="-1">Guía de uso <a class="header-anchor" href="#guia-de-uso" aria-label="Permalink to &quot;Guía de uso&quot;">​</a></h1><h2 id="historial-del-portapapeles" tabindex="-1">Historial del portapapeles <a class="header-anchor" href="#historial-del-portapapeles" aria-label="Permalink to &quot;Historial del portapapeles&quot;">​</a></h2><p>ClipboardxAI se ejecuta desde su <strong>barra de menú</strong>. Cada vez que copia algo, se añade a su historial.</p><ul><li>Haga clic en el icono de la barra de menú para abrir el panel de historial.</li><li>Pase el cursor sobre un elemento y pulse el atajo de la acción, o haga clic para copiarlo de nuevo al portapapeles.</li><li>Use el campo de búsqueda para encontrar un elemento por su texto.</li></ul><h2 id="la-ventana-de-herramientas-de-ia" tabindex="-1">La ventana de herramientas de IA <a class="header-anchor" href="#la-ventana-de-herramientas-de-ia" aria-label="Permalink to &quot;La ventana de herramientas de IA&quot;">​</a></h2><p>La ventana <strong>Herramienta de IA</strong> es donde se ejecutan las acciones. Utiliza un diseño dividido:</p><ul><li><strong>Izquierda</strong> — una lista de herramientas, agrupadas en: <ul><li><strong>IA integrada</strong> — resumen, traducción y otras acciones de IA.</li><li><strong>Local integrada</strong> — herramientas sin conexión (extraer enlaces, contar estadísticas, colapsar líneas en blanco).</li><li><strong>Instaladas</strong> — acciones que añadió desde el Marketplace. Puede arrastrar para <strong>reordenarlas</strong>.</li></ul></li><li><strong>Derecha</strong> — dos paneles: el fragmento <strong>original</strong> a un lado y el <strong>resultado</strong> al otro.</li></ul><p>Las herramientas de IA muestran una insignia de &quot;nube&quot;; las herramientas locales muestran una insignia de &quot;dispositivo&quot;, para que siempre sepa si una acción usa la red.</p><h2 id="ejecutar-una-accion" tabindex="-1">Ejecutar una acción <a class="header-anchor" href="#ejecutar-una-accion" aria-label="Permalink to &quot;Ejecutar una acción&quot;">​</a></h2><ol><li>Seleccione una herramienta de la lista de la izquierda (o acepte una sugerencia inteligente).</li><li>El fragmento actual aparece en el panel <strong>original</strong>.</li><li>El resultado se genera en el panel <strong>resultado</strong>.</li></ol><h3 id="ejecucion-automatica" tabindex="-1">Ejecución automática <a class="header-anchor" href="#ejecucion-automatica" aria-label="Permalink to &quot;Ejecución automática&quot;">​</a></h3><p>Active <strong>Ejecutar automáticamente al generar</strong> en el pie de la ventana. Cuando está activado, la herramienta seleccionada se ejecuta automáticamente en el momento en que copia algo — sin necesidad de clic manual. Las herramientas locales nunca sobrescriben su portapapeles, por lo que la ejecución automática es segura.</p><h2 id="herramientas-locales-integradas" tabindex="-1">Herramientas locales integradas <a class="header-anchor" href="#herramientas-locales-integradas" aria-label="Permalink to &quot;Herramientas locales integradas&quot;">​</a></h2><p>Estas se ejecutan totalmente sin conexión en su Mac:</p><ul><li><strong>Extraer enlaces</strong> — devuelve todas las URL encontradas en el texto.</li><li><strong>Contar estadísticas</strong> — recuento de palabras / caracteres / líneas / frases.</li><li><strong>Colapsar líneas en blanco</strong> — elimina las líneas vacías del texto pegado.</li></ul><h2 id="configuracion-de-la-ia-en-la-nube" tabindex="-1">Configuración de la IA en la nube <a class="header-anchor" href="#configuracion-de-la-ia-en-la-nube" aria-label="Permalink to &quot;Configuración de la IA en la nube&quot;">​</a></h2><p>Para usar acciones de IA, conecte un proveedor en <strong>Ajustes → IA</strong>:</p><ol><li>Elija un proveedor — <strong>DeepSeek</strong>, <strong>MiniMax</strong>, <strong>Zhipu GLM</strong>, <strong>Kimi (Moonshot)</strong>, <strong>Mistral</strong>, <strong>Ollama</strong> (local) u otro servicio compatible con OpenAI.</li><li>Pegue su <strong>API key</strong>. Se almacena en el <strong>Keychain</strong>, nunca se escribe en disco en texto plano.</li><li>Elija un modelo.</li><li>La IA en la nube está desactivada por defecto. Cuando se activa, su fragmento se envía solo al proveedor que configuró.</li></ol><p>Si no se ha establecido ninguna clave, el banner de configuración le lo recuerda dentro de la ventana de la Herramienta de IA.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><ol><li>Abra <strong>Marketplace</strong> desde la ventana de la Herramienta de IA (o la página <a href="/es/marketplace/">Marketplace</a> del sitio).</li><li>Haga clic en <strong>Instalar</strong> en una acción. Esto abre la aplicación mediante el enlace profundo <code>clipboardxai://install?action=&lt;id&gt;</code> y añade la acción a su lista de <strong>Instaladas</strong>.</li></ol><h2 id="atajos-de-teclado" tabindex="-1">Atajos de teclado <a class="header-anchor" href="#atajos-de-teclado" aria-label="Permalink to &quot;Atajos de teclado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atajo</th><th>Acción</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>Abrir el historial del portapapeles</td></tr><tr><td><code>Cmd+,</code></td><td>Abrir Ajustes</td></tr><tr><td><code>Cmd+W</code></td><td>Cerrar ventana</td></tr><tr><td><code>Cmd+Q</code></td><td>Salir de la aplicación</td></tr></tbody></table><blockquote><p>Los atajos exactos pueden variar según la compilación; consulte <strong>Ajustes → Atajos</strong> en la aplicación.</p></blockquote><h2 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h2><p>Abra <strong>ClipboardxAI → Ajustes</strong> (o <code>Cmd+,</code>):</p><ul><li><strong>General</strong>: idioma, inicio al iniciar sesión, tema de apariencia.</li><li><strong>IA</strong>: proveedor en la nube, modelo y API key (Keychain).</li><li><strong>Acciones</strong>: interruptor de ejecución automática, aplicaciones excluidas y orden de las herramientas.</li><li><strong>Privacidad</strong>: opción de IA en la nube, aplicaciones excluidas y controles del historial.</li><li><strong>Marketplace</strong>: explore y gestione las acciones instaladas.</li></ul>',27)])])}const h=e(o,[["render",i]]);export{p as __pageData,h as default};
